// Shared with Achille's website chat, so the app and the website behave
// alike. Generated by scripts/sync-shared.mjs: do not edit it here.

"use client";

import { useEffect, useRef, useState } from "react";
import {
  askFromStorefront,
  choiceLayout,
  choicesFor,
  choose as chooseStep,
  composerVisible,
  conversationKey,
  enterAtStart,
  escalateToTeam,
  initialFlowState,
  liveChoices,
  pendingField,
  startFlow,
  submitText as submitStepText,
  teamCanTakeOver,
  type Choice,
  type CollectField,
  type Conversation,
  type FlowEffect,
  type FlowOutput,
  type FlowPayload,
  type FlowState,
  type Route,
  type Transition,
} from "./flow-engine";
import { postFlowOutcome, rateFlowOutcome, type WidgetEndpoint } from "./flow-api";
import type { FlowStrings } from "./flow-strings";

// A line of the flow's own thread, after the server message it followed
// (null: before them all; see interleave). A rating card keeps the note.
export type FlowItem = FlowOutput & { after: string | null; rating?: number };

function anchored(outputs: readonly FlowOutput[], after: string | null): FlowItem[] {
  return outputs.map((output) => ({ ...output, after }));
}

interface Snapshot {
  // The chat's settings and the conversation on screen (see flowKey).
  key: string;
  // Bumped at each restart, so a reply still on its way is dropped.
  gen: number;
  state: FlowState;
  items: FlowItem[];
  // The bot's next reply is on its way (a short pause, like a person typing).
  typing: boolean;
  // The server copies of the messages already shown as the visitor's bubbles.
  hiddenIds: string[];
  // Where the last handoff sent the conversation.
  route: Route | null;
  error: "invalid_email" | null;
}

const BOT_DELAY_MS = 450;
const TEAM_CHOICE = "__talk_to_team";

// A conversation on screen restarts the flow: one the visitor already had (a
// ticket carries it) shows its history and the composer; a new one starts
// the flow.
function fresh(conversation: Conversation | null, key: string, gen: number, hasTicket: boolean): Snapshot {
  const base = { key, gen, typing: false, hiddenIds: [], route: null, error: null };
  if (!conversation) return { ...base, state: initialFlowState(), items: [] };
  if (hasTicket) {
    const items = conversation.start === "text" ? anchored(startFlow(conversation).bot, null) : [];
    return { ...base, state: initialFlowState("handed_off"), items };
  }
  const started = startFlow(conversation);
  return { ...base, state: started.state, items: anchored(started.bot, null) };
}

// A new conversation acted on from the home screen or the storefront: empty,
// the visitor's action is its first line.
function blank(key: string, gen: number): Snapshot {
  return { key, gen, typing: false, hiddenIds: [], route: null, error: null, state: initialFlowState(), items: [] };
}

// The chat's settings changed (the editor's preview), or another conversation
// took the screen: start over.
function flowKey(conversation: Conversation | null, epoch: number): string {
  return `${conversationKey(conversation)}#${epoch}`;
}

export interface ConversationFlowOptions {
  conversation: Conversation | null;
  aiEnabled: boolean;
  emailKnown: boolean;
  offline: boolean;
  // The editor's preview: nothing is written, a handoff says what would happen.
  preview: boolean;
  // The conversation on screen, counted up each time another one (or a new
  // one) takes the screen, and whether a ticket carries it.
  epoch: number;
  hasTicket: boolean;
  lastServerMessageId: string | null;
  // The last message of the ticket is a reply (the AI's, after a handoff to it).
  lastServerFromAgent: boolean;
  strings: FlowStrings;
  endpoint: WidgetEndpoint;
  // Posts the message that hands over (with `flow`, and the product question
  // it asks when it came from the product page box); resolves its id (""
  // when the server gave none), or null when the send failed.
  handoff: (body: string, flow: FlowPayload, productQuestionId: string | null) => Promise<string | null>;
}

export type SubmitResult = "sent" | "invalid" | "ignored";

export function useConversationFlow(o: ConversationFlowOptions) {
  const conversation = o.conversation;
  const key = flowKey(conversation, o.epoch);
  const [snap, setSnap] = useState<Snapshot>(() => fresh(conversation, key, 0, o.hasTicket));
  if (snap.key !== key) setSnap(fresh(conversation, key, snap.gen + 1, o.hasTicket));

  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
  useEffect(() => {
    const pending = timers.current;
    return () => pending.forEach(clearTimeout);
  }, []);
  // The recorded outcome of the last resolved flow, for its rating.
  const outcome = useRef<Promise<string | null> | null>(null);
  // The product question a storefront ask carries to its handoff (which may
  // wait for the visitor's email).
  const askedQuestionId = useRef<string | null>(null);

  const ctx = {
    aiEnabled: o.aiEnabled,
    emailKnown: o.emailKnown,
    offline: o.offline,
    askEmailText: o.strings.askEmail,
  };

  function update(gen: number, fn: (s: Snapshot) => Snapshot) {
    setSnap((s) => (s.gen === gen ? fn(s) : s));
  }

  function later(fn: () => void) {
    timers.current.push(setTimeout(fn, BOT_DELAY_MS));
  }

  async function run(effect: FlowEffect, gen: number, after: string | null) {
    if (effect.kind === "unavailable") return;
    if (effect.kind === "resolved") {
      outcome.current = o.preview ? Promise.resolve(null) : postFlowOutcome(o.endpoint, effect.path);
      return;
    }
    const teamMessage = conversation?.handoff.team_message.trim() ?? "";
    const team: FlowItem[] =
      effect.flow.route === "team" && teamMessage
        ? [{ from: "bot", text: teamMessage, image_url: null, question: null, after }]
        : [];
    const route = effect.flow.route;
    const questionId = askedQuestionId.current;
    askedQuestionId.current = null;
    if (o.preview) {
      const line = route === "ai" ? o.strings.previewHandoffAi : o.strings.previewHandoffTeam;
      later(() => update(gen, (s) => ({ ...s, route, items: [...s.items, { from: "system", text: line, after }, ...team] })));
      return;
    }
    const openerId = await o.handoff(effect.body, effect.flow, questionId);
    if (openerId === null) return;
    update(gen, (s) => ({
      ...s,
      route,
      hiddenIds: openerId ? [...s.hiddenIds, openerId] : s.hiddenIds,
      items: [...s.items, ...team],
    }));
  }

  // Shows `next` (with the visitor's bubble at once and the bot's reply after
  // a short pause) and runs what the transition asks for. `next` replaces the
  // snapshot of generation `from` (a new conversation is the next one).
  function commit(next: Snapshot, t: Transition | null, from = next.gen) {
    const gen = next.gen;
    // Everything this action shows comes after the ticket's last message;
    // a new conversation has none.
    const after = gen === from ? o.lastServerMessageId : null;
    const visitor: FlowItem[] = t?.visitor ? [{ from: "visitor", text: t.visitor, after }] : [];
    const replies = anchored(t?.bot ?? [], after);
    setSnap((s) =>
      s.gen !== from
        ? s
        : {
            ...next,
            state: t ? t.state : next.state,
            // Set at the click: the "talk to the team" offer goes at once
            // (and for good once nobody could take over).
            route:
              t?.effect?.kind === "handoff" ? t.effect.flow.route : t?.effect?.kind === "unavailable" ? null : next.route,
            items: [...next.items, ...visitor],
            typing: replies.length > 0 || (t ? false : next.typing),
            error: t?.error ?? null,
          }
    );
    if (replies.length) later(() => update(gen, (s) => ({ ...s, typing: false, items: [...s.items, ...replies] })));
    if (t?.effect) void run(t.effect, gen, after);
  }

  const startStep = conversation?.flow.start_step_id
    ? conversation.flow.steps.get(conversation.flow.start_step_id) ?? null
    : null;
  const homeChoices: Choice[] =
    conversation?.home.opening === "buttons" && conversation.start !== "text" && startStep
      ? choicesFor(conversation, { ...startStep, ask_resolved: false }, false)
      : [];
  // Once the AI answered (in a preview: once handed to it), the visitor can
  // ask for a person, when the chat has a team to take over.
  const offerTeam =
    !!conversation &&
    teamCanTakeOver(conversation) &&
    snap.route === "ai" &&
    !snap.state.pending &&
    !snap.typing &&
    (o.preview || o.lastServerFromAgent);
  const teamChoice: Choice = {
    key: TEAM_CHOICE, label: o.strings.talkToTeam, action: "team", target_step_id: null, url: null, workflow_id: null,
  };
  const live = conversation && !snap.typing ? liveChoices(conversation, snap.state) : [];
  const choices = live.length === 0 && offerTeam ? [teamChoice] : live;
  const field: CollectField | null = conversation ? pendingField(conversation, snap.state) : null;

  // A new conversation for an action of the home screen or the storefront
  // (`epoch`: the one the caller just put on screen), at the start step.
  function blankAt(epoch: number): Snapshot {
    return blank(flowKey(conversation, epoch), snap.gen + 1);
  }

  return {
    items: snap.items,
    typing: snap.typing,
    error: snap.error,
    hiddenIds: snap.hiddenIds,
    choices,
    layout: choiceLayout(choices),
    composerVisible: conversation ? composerVisible(conversation, snap.state, o.hasTicket) : true,
    field,
    homeChoices,
    homeComposer: homeChoices.length > 0 && conversation?.start === "buttons_text",

    // A start button on the home screen: a new conversation, acting from the
    // first step.
    chooseFromHome(choice: Choice, epoch: number) {
      if (!conversation || choice.action === "link") return;
      const base = blankAt(epoch);
      const state = enterAtStart(conversation, base.state);
      commit({ ...base, state }, chooseStep(conversation, state, choice, ctx), snap.gen);
    },

    choose(choice: Choice) {
      if (!conversation) return;
      const t =
        choice.key === TEAM_CHOICE
          ? escalateToTeam(conversation, snap.state, choice.label, ctx)
          : chooseStep(conversation, snap.state, choice, ctx);
      if (t) commit(snap, t);
    },

    // What the visitor wrote. "ignored": not the flow's business (a ticket
    // carries the conversation), send it as a plain message.
    submit(text: string): SubmitResult {
      if (!conversation) return "ignored";
      const t = submitStepText(conversation, snap.state, text, ctx);
      if (!t && o.preview && text.trim()) {
        // No ticket in a preview: the message stays in the flow's thread.
        const line: FlowItem = { from: "visitor", text: text.trim(), after: o.lastServerMessageId };
        update(snap.gen, (s) => ({ ...s, items: [...s.items, line] }));
        return "sent";
      }
      if (!t) return "ignored";
      commit(snap, t);
      return t.error ? "invalid" : "sent";
    },

    // The home screen's composer: a new conversation, read from the first
    // step.
    submitFromHome(text: string, epoch: number): SubmitResult {
      if (!conversation) return "ignored";
      const base = blankAt(epoch);
      const state = enterAtStart(conversation, base.state);
      const t = submitStepText(conversation, state, text, ctx);
      if (!t) return "ignored";
      commit({ ...base, state }, t, snap.gen);
      return t.error ? "invalid" : "sent";
    },

    // A question from the product page box (on the storefront, outside the
    // chat): it goes to the conversation like free text, whatever the flow
    // was showing. false: a ticket already carries the conversation, the
    // caller sends it as a plain message.
    ask(text: string, productQuestionId: string | null): boolean {
      if (!conversation) return false;
      const t = askFromStorefront(conversation, snap.state, text, ctx);
      if (!t) return false;
      askedQuestionId.current = t.effect?.kind === "unavailable" ? null : productQuestionId;
      commit({ ...snap, typing: false }, t);
      return true;
    },

    // The same question when it opens a new conversation (`epoch`: the one
    // the caller just put on screen).
    askNew(text: string, productQuestionId: string | null, epoch: number): boolean {
      if (!conversation) return false;
      const base = blankAt(epoch);
      const t = askFromStorefront(conversation, base.state, text, ctx);
      if (!t) return false;
      askedQuestionId.current = t.effect?.kind === "unavailable" ? null : productQuestionId;
      commit(base, t, snap.gen);
      return true;
    },

    rate(index: number, value: number) {
      const item = snap.items[index];
      if (!item || item.from !== "csat" || item.rating) return;
      update(snap.gen, (s) => ({
        ...s,
        items: s.items.map((it, i) => (i === index ? { ...it, rating: value } : it)),
      }));
      if (o.preview) return;
      void outcome.current?.then((id) => {
        if (id) void rateFlowOutcome(o.endpoint, id, value);
      });
    },
  };
}
